// НАСТРОЙКИ КЛИЕНТА
const BUSINESS = 'Стоматология «Пример»';
const CITY = 'Москва';
const MANAGER_CHAT_ID = '000000000';

const msg = $('Сообщение в бота').first().json.message || {};
const userText = (msg.text || '').trim();
const userChatId = msg.chat?.id;
const userName = [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || 'клиент';
const username = msg.from?.username ? '@' + msg.from.username : 'без ника';

// Собираем базу знаний из таблицы: колонки "Вопрос" и "Ответ"
const rows = $input.all().map(i => i.json).filter(r => r['Вопрос'] && r['Ответ']);
const knowledge = rows
  .map((r, i) => `${i + 1}. В: ${r['Вопрос']}\n   О: ${r['Ответ']}`)
  .join('\n\n');

const systemPrompt = `Ты консультант компании "${BUSINESS}" (${CITY}) в Telegram.

БАЗА ЗНАНИЙ (единственный источник фактов):
${knowledge}

Правила:
- Отвечай ТОЛЬКО тем, что есть в базе знаний. Ничего не выдумывай: ни цены, ни адреса, ни сроки, ни акции.
- Если ответа в базе нет, либо человек просит записаться, обсудить скидку, пожаловаться или задаёт медицинский вопрос - НЕ отвечай по существу, передай менеджеру.
- Не ставь диагнозы и не давай медицинских рекомендаций ни при каких условиях.
- 2-4 предложения, живой разговорный русский, на "вы".
- Не пиши, что ты бот или ИИ, но и не утверждай, что ты человек. Если спросят прямо - скажи, что вы автоматический помощник и позовите менеджера.

Ответь СТРОГО одним JSON-объектом без markdown-обёртки:
{"reply": "текст для клиента", "handoff": true|false, "reason": "почему передаём менеджеру, пусто если не передаём"}`;

return [{
  json: {
    userText,
    userChatId,
    userName,
    username,
    managerChatId: MANAGER_CHAT_ID,
    business: BUSINESS,
    systemPrompt
  }
}];

const ctx = $('Собрать контекст').item.json;
const resp = $json;

const FALLBACK = 'Секунду, зову менеджера — он ответит здесь же.';

if (resp.stop_reason === 'refusal') {
  return [{ json: { ...ctx, reply: FALLBACK, handoff: true, reason: 'модель отказалась отвечать' } }];
}

const raw = (resp.content || [])
  .filter(b => b.type === 'text')
  .map(b => b.text)
  .join('')
  .trim();

let parsed;
try {
  // на случай, если модель обернула в ```json
  const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { ...ctx, reply: FALLBACK, handoff: true, reason: 'не удалось разобрать ответ модели' } }];
}

return [{
  json: {
    ...ctx,
    reply: parsed.reply || FALLBACK,
    handoff: parsed.handoff === true,
    reason: parsed.reason || ''
  }
}];
